import sys, random
from functools import lru_cache
sys.setrecursionlimit(10000)
def solve(boxes, M):
    N=len(boxes)
    # state: tuple of owned entries: (box_idx, type or -1, count); unowned as frozenset via bitmask
    @lru_cache(None)
    def f(owned, mask):
        best=None
        for t in range(M):
            opts=[0]
            # owned boxes
            for k,(bi,ty,c) in enumerate(owned):
                V=boxes[bi][0]
                if ty==t and c<V:
                    no=list(owned); no[k]=(bi,t,c+1)
                    opts.append(1+f(tuple(no),mask))
                if ty==-1:
                    no=list(owned); no[k]=(bi,t,1)
                    opts.append(1+f(tuple(no),mask))
            for j in range(N):
                if not (mask>>j)&1:
                    V,P=boxes[j]
                    if V>=1:
                        no=owned+((j,t,1),)
                        opts.append(1-P+f(no,mask|(1<<j)))
            v=max(opts)
            if best is None or v<best: best=v
        return best
    return f((),0)
def brute(N,M,boxes):
    return solve(boxes,M)
