class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)
        N = L + 1
        C = [[0] * (N + 1) for _ in range(N + 1)]
        for i in range(N + 1):
            C[i][0] = 1
            for j in range(1, i + 1):
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD
        h = [0] * (N + 1)
        for m in range(2, N + 1):
            h[m] = 1 + h[bin(m).count('1')]
        G = [c for c in range(1, N + 1) if h[c] <= k - 1]
        ans = 0
        cnt = 0
        for i, ch in enumerate(s):
            if ch == '1':
                m = L - i - 1
                for c in G:
                    need = c - cnt
                    if 0 <= need <= m:
                        ans += C[m][need]
                cnt += 1
        return ans % MOD

