import sys
from collections import deque
def main():
    d=sys.stdin.read().split()
    N,M,Q=int(d[0]),int(d[1]),int(d[2])
    p=3
    P=[]
    for i in range(M):
        s=int(d[p]);t=int(d[p+1]);p+=2
        P.append((s,t))
    out=[]
    for _ in range(Q):
        L=int(d[p]);R=int(d[p+1]);p+=2
        par=list(range(N))
        def f(x):
            while par[x]!=x:
                par[x]=par[par[x]];x=par[x]
            return x
        ok=True
        segs=[]
        for i in range(L-1,R):
            s,t=P[i]
            if s<t:
                a,b,up=s-1,t-1,True
            else:
                a,b,up=t-1,s-1,False
            segs.append((a,b,up))
            ra,rb=f(a),f(b)
            if ra!=rb: par[ra]=rb
        adj={}
        indeg={}
        for a,b,up in segs:
            ca=f(a)
            for j in range(a+1,b):
                cj=f(j)
                if cj==ca:
                    ok=False;break
                if up: u,v=ca,cj
                else: u,v=cj,ca
                adj.setdefault(u,[]).append(v)
                indeg[v]=indeg.get(v,0)+1
            if not ok: break
        if ok:
            nodes=set(f(x) for x in range(N))
            q=deque([x for x in nodes if indeg.get(x,0)==0])
            cnt=0
            while q:
                x=q.popleft();cnt+=1
                for y in adj.get(x,[]):
                    indeg[y]-=1
                    if indeg[y]==0: q.append(y)
            if cnt!=len(nodes): ok=False
        out.append("Yes" if ok else "No")
    print("\n".join(out))
main()

