import sys

def solve(n, A):
    L = 64
    def cM(q):
        while q % 2 == 0:
            q //= 2
        return q % 4 == 3
    NEG = -10**9
    dp = {0: 0}
    dead = NEG
    for t in range(L):
        mod = 1 << t
        grp = {}
        for a in A:
            grp.setdefault(a % mod, []).append(a)
        alive = set(grp.keys())
        ndp = {}
        for c, sc in dp.items():
            lst = grp.get(((1 << (t - 1)) - c) % mod, []) if t >= 1 else []
            cnt = [0, 0]
            for a in lst:
                cnt[((a + c) >> t) & 1] += 1
            for b in (0, 1):
                c2 = c + (b << t)
                g = cnt[1 - b]
                if (-c2) % mod in alive:
                    if sc + g > ndp.get(c2, NEG):
                        ndp[c2] = sc + g
                else:
                    dead = max(dead, sc + g)
        dp = ndp
    mod = 1 << L
    grp = {}
    for a in A:
        grp.setdefault(a % mod, []).append(a)
    best = dead
    for c, sc in dp.items():
        lst = grp.get(((1 << (L - 1)) - c) % mod, [])
        zl = grp.get((-c) % mod, [])
        for H in range(0, 17):
            if c == 0 and H == 0:
                continue
            tot = sc
            for a in lst:
                if ((((a + c) >> L) + H) & 1) == 1:
                    tot += 1
            for a in zl:
                if cM(((a + c) >> L) + H):
                    tot += 1
            best = max(best, tot)
    return best

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    A = list(map(int, data[1:1 + n]))
    print(solve(n, A))

main()

