import sys

def main():
    data = sys.stdin.read().split()
    n, m = int(data[0]), int(data[1])
    rows = [0] * n
    idx = 2
    for _ in range(m):
        u = int(data[idx]) - 1
        v = int(data[idx + 1]) - 1
        idx += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u
    # Gaussian elimination over GF(2) to RREF
    r = 0
    piv_cols = []
    for c in range(n):
        sel = -1
        for i in range(r, n):
            if (rows[i] >> c) & 1:
                sel = i
                break
        if sel == -1:
            continue
        rows[r], rows[sel] = rows[sel], rows[r]
        for i in range(n):
            if i != r and (rows[i] >> c) & 1:
                rows[i] ^= rows[r]
        piv_cols.append(c)
        r += 1
    pivset = set(piv_cols)
    free = [c for c in range(n) if c not in pivset]
    basis = []
    for f in free:
        vec = 1 << f
        for k, p in enumerate(piv_cols):
            if (rows[k] >> f) & 1:
                vec |= 1 << p
        basis.append(vec)
    X = []
    for v in range(n):
        val = 0
        for j, b in enumerate(basis):
            if (b >> v) & 1:
                val |= 1 << j
        X.append(val)
    if any(x == 0 for x in X):
        print("No")
    else:
        print("Yes")
        print(" ".join(map(str, X)))

