from typing import List
class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid); m = len(grid[0])
        dirs = [(1,1),(1,-1),(-1,-1),(-1,1)]
        def need(a):
            return 0 if a == 2 else 2
        P = []
        Q = []
        for di, dj in dirs:
            p = [[0]*m for _ in range(n)]
            rows = range(n) if di >= 0 else range(n-1, -1, -1)
            cols = list(range(m)) if dj >= 0 else list(range(m-1, -1, -1))
            for i in rows:
                pi = i - di
                gi = grid[i]; pr = p[i]
                for j in cols:
                    v = gi[j]
                    if v == 1:
                        pr[j] = 1
                        continue
                    pj = j - dj
                    if 0 <= pi < n and 0 <= pj < m and p[pi][pj] > 0 and need(grid[pi][pj]) == v:
                        pr[j] = p[pi][pj] + 1
            P.append(p)
            q = [[0]*m for _ in range(n)]
            rows2 = range(n-1, -1, -1) if di >= 0 else range(n)
            cols2 = list(range(m-1, -1, -1)) if dj >= 0 else list(range(m))
            for i in rows2:
                ni = i + di
                gi = grid[i]; qr = q[i]
                for j in cols2:
                    v = gi[j]
                    qr[j] = 1
                    nj = j + dj
                    if 0 <= ni < n and 0 <= nj < m and need(v) == grid[ni][nj]:
                        qr[j] = 1 + q[ni][nj]
            Q.append(q)
        best = 0
        for k in range(4):
            pk = P[k]; qk = Q[(k+1) % 4]
            for i in range(n):
                for j in range(m):
                    if pk[i][j] > 0:
                        t = pk[i][j] + qk[i][j] - 1
                        if t > best:
                            best = t
        return best

