from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        def f(a, b, q):
            # a odds, b evens remaining; first element parity q (1=odd, 0=even)
            if a < 0 or b < 0:
                return 0
            if a + b == 0:
                return 1
            if q == 1:
                ok = (a == b or a == b + 1)
            else:
                ok = (b == a or b == a + 1)
            return factorial(a) * factorial(b) if ok else 0

        o = (n + 1) // 2
        e = n // 2
        total = f(o, e, 1) + f(o, e, 0)
        if k > total:
            return []
        remaining = list(range(1, n + 1))
        res = []
        prev = None
        a, b = o, e
        for _ in range(n):
            chosen = False
            for idx, x in enumerate(remaining):
                px = x % 2
                if prev is not None and px == prev:
                    continue
                na, nb = (a - 1, b) if px == 1 else (a, b - 1)
                if na + nb == 0:
                    c = 1
                else:
                    c = f(na, nb, 1 - px)
                if k <= c:
                    res.append(x)
                    remaining.pop(idx)
                    a, b = na, nb
                    prev = px
                    chosen = True
                    break
                k -= c
            if not chosen:
                return []
        return res

