    D0=[C[i] for i in range(n) if A[i]==1 and B[i]==0]
    U0=[C[i] for i in range(n) if A[i]==0 and B[i]==1]
    M1=sorted([C[i] for i in range(n) if A[i]==1 and B[i]==1],reverse=True)
    m=len(D0)+len(U0)
    vals=sorted(set(C)); idx={v:i+1 for i,v in enumerate(vals)}
    V=len(vals)
    class S:
        def __init__(s):
            s.bc=[0]*(V+1); s.bs=[0]*(V+1); s.cnt=0; s.tot=0; s.cost=0
        def add(s,x):
            i=idx[x]
            less_c=0; less_s=0; j=i
            while j>0:
                less_c+=s.bc[j]; less_s+=s.bs[j]; j-=j&-j
            G=s.cnt-less_c
            delta=x*G+less_s
            s.cost+=delta
            j=i
            while j<=V:
                s.bc[j]+=1; s.bs[j]+=x; j+=j&-j
            s.cnt+=1; s.tot+=x
    Dset=S(); Uset=S()
    for x in D0: Dset.add(x)
    for x in U0: Uset.add(x)
    sM=sum(M1); sP=0
    def total(p):
        costD=Dset.cost
