class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        h = (n + 1) // 2
        w = []
        for i in range(h):
            j = n - 1 - i
            if i == j:
                w.append(pow(10, i, k))
            else:
                w.append((pow(10, i, k) + pow(10, j, k)) % k)
        feas = [None] * (h + 1)
        feas[h] = [False] * k
        feas[h][0] = True
        for i in range(h - 1, -1, -1):
            nxt = feas[i + 1]
            cur = [False] * k
            lo = 1 if i == 0 else 0
            for r in range(k):
                for d in range(lo, 10):
                    if nxt[(r - d * w[i]) % k]:
                        cur[r] = True
                        break
            feas[i] = cur
        if not feas[0][0]:
            return ""
        digs = []
        R = 0
        for i in range(h):
            lo = 1 if i == 0 else 0
            for d in range(9, lo - 1, -1):
                if feas[i + 1][(R - d * w[i]) % k]:
                    digs.append(d)
                    R = (R - d * w[i]) % k
                    break
