from typing import List
class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        nxt = [n] * n
        st = []
        for i in range(n):
            while st and nums[st[-1]] < nums[i]:
                nxt[st.pop()] = i
            st.append(i)
        S = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            S[i] = nums[i] * (nxt[i] - i) + S[nxt[i]]
        pre = [0] * (n + 1)
        for i in range(n):
            pre[i + 1] = pre[i] + nums[i]
        sp = [list(range(n))]
        j = 1
        while (1 << j) <= n:
            prev = sp[-1]
            h = 1 << (j - 1)
            cur = []
            for i in range(n - (1 << j) + 1):
                a = prev[i]; b = prev[i + h]
                if nums[b] > nums[a]:
                    cur.append(b)
                else:
                    cur.append(a)
            sp.append(cur)
            j += 1
        def argmax(l, r):
            length = r - l + 1
            t = length.bit_length() - 1
            a = sp[t][l]; b = sp[t][r - (1 << t) + 1]
            return b if nums[b] > nums[a] else a
        def cost(l, r):
            c = argmax(l, r)
            F = S[l] - S[c] + nums[c] * (r + 1 - c)
            return F - (pre[r + 1] - pre[l])
        ans = 0
        r = -1
        for l in range(n):
            if r < l - 1:
                r = l - 1
            while r + 1 < n and cost(l, r + 1) <= k:
                r += 1
            ans += r - l + 1
        return ans

