class Solution:
    def makeStringGood(self, s: str) -> int:
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1
        n = len(s)
        best = n
        for f in range(1, n + 1):
            total = 0
            carry = 0
            for i in range(26):
                avail = cnt[i] + carry
                if avail == 0:
                    carry = 0
                    continue
                if avail >= f:
                    excess = avail - f
                    total += excess
                    if i + 1 < 26:
                        carry = min(excess, max(0, f - cnt[i + 1]))
                    else:
                        carry = 0
                else:
                    total += f - avail
                    carry = 0
                if total >= best:
                    break
            else:
                best = min(best, total)
        return best

