import sys
def main():
    sys.setrecursionlimit(10000)
    data=sys.stdin.read().split()
    N,M,L=int(data[0]),int(data[1]),int(data[2])
    A=list(map(int,data[3:3+N])); B=list(map(int,data[3+N:3+N+M])); C=list(map(int,data[3+N+M:3+N+M+L]))
    vals=A+B+C; K=len(vals)
    tm=(1<<N)-1; am=((1<<M)-1)<<N
    full=(1<<K)-1; memo={}
    def f(t,a,turn):
        key=(t,a,turn)
        if key in memo: return memo[key]
        H = t if turn==0 else a
        table = full & ~(t|a)
        res=False
        for c in range(K):
            if res: break
            if not (H>>c)&1: continue
            nH=H & ~(1<<c)
            cand=[]
            if turn==0: cand.append((nH,a))
            else: cand.append((t,nH))
            for d in range(K):
                if (table>>d)&1 and vals[d]<vals[c]:
                    if turn==0: cand.append((nH|(1<<d),a))
                    else: cand.append((t,nH|(1<<d)))
            for nt,na in cand:
                if not f(nt,na,1-turn):
                    res=True;break
        memo[key]=res
        return res
    print("Takahashi" if f(tm,am,0) else "Aoki")
