from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)

        def occ(t, x):
            m = len(x)
            if m == 0:
                return list(range(n + 1))
            fail = [0] * m
            k = 0
            for i in range(1, m):
                while k and x[i] != x[k]:
                    k = fail[k - 1]
                if x[i] == x[k]:
                    k += 1
                fail[i] = k
            res = []
            k = 0
            for i, ch in enumerate(t):
                while k and ch != x[k]:
                    k = fail[k - 1]
                if ch == x[k]:
                    k += 1
                if k == m:
                    res.append(i - m + 1)
                    k = fail[k - 1]
            return res

        A = occ(s, a)
        B = occ(s, b)
        C = occ(s, c)
        la, lb, lc = len(a), len(b), len(c)
        ans = -1
        for i in A:
            idx = bisect_left(B, i + la)
            if idx == len(B):
                continue
            j = B[idx]
            idx2 = bisect_left(C, j + lb)
            if idx2 == len(C):
                continue
            k = C[idx2]
            length = k + lc - i
            if ans == -1 or length < ans:
                ans = length
        return ans

