import sys
def main():
    data = sys.stdin.read().split()
    n, k = int(data[0]), int(data[1])
    a = [int(x) for x in data[2:2+n]]
    total = 0
    for x in a:
        total ^= x
    if k > n - k:
        m = n - k
        base = total
    else:
        m = k
        base = 0
    if m == 0:
        print(base)
        return
    best = [0]
    sys.setrecursionlimit(10000)
    def rec(start, r, cur):
        if r == 1:
            v = max(cur ^ x for x in a[start:n])
            if v > best[0]:
                best[0] = v
            return
        for i in range(start, n - r + 1):
            rec(i + 1, r - 1, cur ^ a[i])
    rec(0, m, 0)
    print(best[0] ^ base)
main()

