import sys

def main():
    data = sys.stdin.read().split()
    t = int(data[0])
    idx = 1
    out = []
    for _ in range(t):
        N = int(data[idx]); A = data[idx+1]; B = data[idx+2]
        idx += 3
        p = [i+1 for i in range(N) if A[i] == '1']
        s = [i+1 for i in range(N) if B[i] == '1']
        K = len(p); M = len(s)
        if M > K:
            out.append("-1")
            continue
        L = max(s[0]-p[0], p[-1]-s[-1], 0)
        F = [0, 0]
        for j in range(K-1):
            g = p[j+1]-p[j]
            for sg in (0, 1):
                m = F[sg]
                if m+1 <= M-1:
                    diff = s[m+1]-s[m]
                    if diff < g or (diff == g and (s[m]-p[j]) % 2 == sg):
                        F[sg] += 1
        if F[L % 2] >= M-1:
            out.append(str(L))
        elif F[(L+1) % 2] >= M-1:
            out.append(str(L+1))
        else:
            out.append("-1")
    print("\n".join(out))

main()

