from collections import deque

def bfs(N, A, B):
    start = frozenset(i+1 for i in range(N) if A[i]=='1')
    tgt = frozenset(i+1 for i in range(N) if B[i]=='1')
    dist={start:0}; dq=deque([start])
    while dq:
        s=dq.popleft()
        if s==tgt: return dist[s]
        for c in range(1,N+1):
            t=frozenset((j-1 if c>j else (j+1 if c<j else j)) for j in s)
            if t not in dist:
                dist[t]=dist[s]+1; dq.append(t)
    return -1

def feas(T, p, s):
    K=len(p); M=len(s)
    if M==0 or K<M: return False
    R={0} if abs(s[0]-p[0])<=T else set()
    for j in range(K-1):
        g=p[j+1]-p[j]
        nr=set()
        for m in R:
            nr.add(m)
            if m+1<M and s[m+1]-s[m]<=g: nr.add(m+1)
        R={m for m in nr if abs(s[m]-p[j+1])<=T}
        if not R: return False
    return (M-1) in R

