from typing import List
class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)
        for c in children:
            c.sort()
        size = [1]*n
        order = []
        stack = [0]
        while stack:
            x = stack.pop()
            order.append(x)
            stack.extend(children[x])
        for x in reversed(order):
            if parent[x] >= 0:
                size[parent[x]] += size[x]
        post = []
        st = [(0, 0)]
        while st:
            x, idx = st.pop()
            if idx < len(children[x]):
                st.append((x, idx + 1))
                st.append((children[x][idx], 0))
            else:
                post.append(x)
        pos = [0]*n
        for k, x in enumerate(post):
            pos[x] = k
        T = [s[x] for x in post]
        t = ['#']
        for ch in T:
            t.append(ch); t.append('#')
        m = len(t)
        p = [0]*m
        c = r = 0
        for i in range(m):
            if i < r:
                p[i] = min(r - i, p[2*c - i])
            while i - p[i] - 1 >= 0 and i + p[i] + 1 < m and t[i-p[i]-1] == t[i+p[i]+1]:
                p[i] += 1
            if i + p[i] > r:
                c, r = i, i + p[i]
        ans = []
        for x in range(n):
            hi = pos[x]
            lo = hi - size[x] + 1
            L = hi - lo + 1
            ans.append(p[lo + hi + 1] >= L)
        return ans

