from typing import List

class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        P = [0] * (n + 1)
        for i in range(n):
            P[i + 1] = P[i] + nums[i]
        INF = float('inf')
        minv = [INF] * k
        ans = -INF
        for i in range(k, n + 1):
            j = i - k
            r = i % k
            if P[j] < minv[r]:
                minv[r] = P[j]
            v = P[i] - minv[r]
            if v > ans:
                ans = v
        return int(ans)

