class Solution:
    def countPairs(self, nums: List[int]) -> int:
        def variants(s, L):
            s = s.zfill(L)
            res = {s}
            arr = list(s)
            n = len(arr)
            for i in range(n):
                for j in range(i + 1, n):
                    arr[i], arr[j] = arr[j], arr[i]
                    res.add(''.join(arr))
                    arr[i], arr[j] = arr[j], arr[i]
            return res

        def almost(x, y):
            a, b = str(x), str(y)
            L = max(len(a), len(b))
            a2, b2 = a.zfill(L), b.zfill(L)
            if a2 == b2:
                return True
            return b2 in variants(a2, L) or a2 in variants(b2, L)

        cnt = 0
        n = len(nums)
        for i in range(n):
            for j in range(i + 1, n):
                if almost(nums[i], nums[j]):
                    cnt += 1
        return cnt

