class Solution:
    def minZeroArray(self, nums, queries):
        n = len(nums)
        reach = [1] * n  # bitmask of achievable total decrements per index
        def done():
            return all((reach[i] >> nums[i]) & 1 for i in range(n))
        if done():
            return 0
        for k, (l, r, v) in enumerate(queries, 1):
            for i in range(l, r + 1):
                reach[i] |= reach[i] << v
            if done():
                return k
        return -1

