                for nd in (digit - 1, digit + 1):
                    if 0 <= nd <= 9:
                        v = base + nd * p10[i]
                        if isp(v):
                            continue
                        nd_cost = d + v
                        if nd_cost < dist.get(v, float('inf')):
                            dist[v] = nd_cost
                            heapq.heappush(pq, (nd_cost, v))
