class Solution:
    def beautifulSplits(self, nums):
        n = len(nums)
        z = [0] * n
        z[0] = n
        l = r = 0
        for i in range(1, n):
            if i < r:
                z[i] = min(r - i, z[i - l])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > r:
                l, r = i, i + z[i]
        total = 0
        for i in range(1, n - 1):
            hiB = min(n - 1, i + z[i], (n + i) // 2)
            B = max(0, hiB - i)
            A = 0
            inter = 0
            if z[i] >= i:
                A = max(0, n - 2 * i)
                inter = max(0, hiB - 2 * i + 1)
            total += A + B - inter
        return total

