    def maxRemovals(self, source, pattern, targetIndices):
        m = len(pattern)
        NEG = -10**9
        tgt = [False]*len(source)
        for t in targetIndices:
            tgt[t] = True
        dp = [NEG]*(m+1)
        dp[0] = 0
        pos = {}
        for j, ch in enumerate(pattern):
            pos.setdefault(ch, []).append(j+1)
        for i, c in enumerate(source):
            t = 1 if tgt[i] else 0
            js = pos.get(c, ())
            if t:
                old = dp[:]
                for k in range(m+1):
                    dp[k] = old[k] + 1 if old[k] > NEG // 2 else NEG
                for k in js:
                    if old[k-1] > NEG // 2 and old[k-1] > dp[k]:
                        dp[k] = old[k-1]
            else:
                old = dp[:]
                for k in js:
                    if old[k-1] > dp[k]:
                        dp[k] = old[k-1]
        return dp[m] if dp[m] > NEG // 2 else 0

