        NEG = -10**9
        tgt = [False]*len(source)
        for t in targetIndices:
            tgt[t] = True
        # dp[j]: max removals with pattern[:j] matched, using source prefix
        dp = [NEG]*(m+1)
        dp[0] = 0
        # positions of pattern chars per letter
        pos = {}
        for j, ch in enumerate(pattern):
            pos.setdefault(ch, []).append(j+1)  # dp index j+1 gets matched from dp[j]
        for i, c in enumerate(source):
            t = 1 if tgt[i] else 0
            js = pos.get(c, ())
            if t:
                # all states get +1 (removal option); matching ones may also take old dp[j-1]
                old = dp[:]
                for k in range(m+1):
                    dp[k] = old[k] + 1 if old[k] > NEG // 2 else NEG
                for k in js:
                    if old[k-1] > NEG // 2 and old[k-1] > dp[k]:
                        dp[k] = old[k-1]
            else:
                for k in js:
                    if dp[k-1] > dp[k]:
                        # descending order needed to use old values
                        pass
                old = dp[:]
                for k in js:
                    if old[k-1] > dp[k]:
                        dp[k] = old[k-1]
        return dp[m] if dp[m] > NEG // 2 else 0

