import heapq
from typing import List

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Each node only needs one outgoing edge in a tree toward 0 (threshold >= 1),
        # so answer = max over nodes of minimax-bottleneck path cost to node 0.
        radj = [[] for _ in range(n)]
        for a, b, w in edges:
            radj[b].append((a, w))
        INF = float('inf')
        dist = [INF] * n
        dist[0] = 0
        heap = [(0, 0)]
        while heap:
            d, u = heapq.heappop(heap)
            if d != dist[u]:
                continue
            for v, w in radj[u]:
                nd = max(d, w)
                if nd < dist[v]:
                    dist[v] = nd
                    heapq.heappush(heap, (nd, v))
        ans = 0
        for i in range(1, n):
            if dist[i] == INF:
                return -1
            ans = max(ans, dist[i])
        return ans

